import{_ as t,c as a,o as i,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Develop a feature from acceptance criteria","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/feature-development.md","filePath":"ai-assisted-engineering/feature-development.md"}'),s={name:"ai-assisted-engineering/feature-development.md"};function r(o,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_3-develop-a-feature-from-acceptance-criteria" tabindex="-1">Develop a feature from acceptance criteria <a class="header-anchor" href="#_3-develop-a-feature-from-acceptance-criteria" aria-label="Permalink to “Develop a feature from acceptance criteria”">​</a></h1><p>Now add a small feature to the same catalogue: search titles and return a bounded result list. Unlike a bug fix, a feature needs you to agree on behavior that did not exist before. Resolve the contract before choosing a library.</p><h2 id="make-the-request-testable" tabindex="-1"><span class="hub-section-number">1 </span>Make the request testable <a class="header-anchor" href="#make-the-request-testable" aria-label="Permalink to “1 Make the request testable”">​</a></h2><p>For this study task, the declared contract is:</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Example</th></tr></thead><tbody><tr><td>Query is optional; trim it and match titles case-insensitively</td><td><code>&#39; api &#39;</code> matches <code>&#39;API&#39;</code></td></tr><tr><td>Empty query includes all notes</td><td><code>query: &#39;&#39;</code> keeps every candidate before limiting</td></tr><tr><td>Sort by title, then ID, before applying the limit</td><td>Equal titles have predictable order</td></tr><tr><td>Default limit is 10; explicit zero means no results</td><td><code>limit: 0</code> returns <code>[]</code></td></tr><tr><td>Limit must be an integer from 0 to 50</td><td>Reject negative, fractional, null and string values at runtime</td></tr><tr><td>Preserve the original array and objects</td><td>Searching does not change another view</td></tr><tr><td>No match and empty input return an empty array</td><td>No invented fallback note</td></tr></tbody></table><p>This example uses simple lowercase substring matching and code-unit sort order. It does not promise locale-aware ranking or semantic search. Those would require a different contract and examples.</p><h2 id="plan-a-narrow-implementation" tabindex="-1"><span class="hub-section-number">2 </span>Plan a narrow implementation <a class="header-anchor" href="#plan-a-narrow-implementation" aria-label="Permalink to “2 Plan a narrow implementation”">​</a></h2><p>Reuse the corrected sorter. Validate options, normalize the query, filter titles, sort candidates and apply the limit. A new vector database, web framework or model is unnecessary for this feature.</p><p>Read the <a href="./../workbench/engineering/ai-engineering/catalogue/">reference source and checks</a>. The undefined-only default is deliberate:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> limit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> options.limit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> undefined</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> options.limit;</span></span></code></pre></div><p>Using <code>options.limit || 10</code> would turn the valid zero into ten. This resembles the older retry defect, but the new requirement is a list feature with its own acceptance cases.</p><h2 id="use-the-assistant-in-increments" tabindex="-1"><span class="hub-section-number">3 </span>Use the assistant in increments <a class="header-anchor" href="#use-the-assistant-in-increments" aria-label="Permalink to “3 Use the assistant in increments”">​</a></h2><p>Ask it to map criteria to checks, identify affected callers and propose the smallest public API. Implement the pure helper first. Only then connect it to a UI or endpoint, where external JSON needs validation and an authenticated note catalogue. TypeScript types are not runtime checks for HTTP input.</p><p>Keep the diff focused: helper, meaningful checks and a short behavior explanation. Preserve the supplied compiler/test configuration and restricted test directories. Avoid unrelated “cleanup” that obscures the new feature.</p><h2 id="review-edge-cases-explicitly" tabindex="-1"><span class="hub-section-number">4 </span>Review edge cases explicitly <a class="header-anchor" href="#review-edge-cases-explicitly" aria-label="Permalink to “4 Review edge cases explicitly”">​</a></h2><p>Check <code>limit: 0</code>, matching after whitespace normalization, two notes with the same title, no matches and invalid options. A result count test alone could pass while the wrong notes are returned. Assert identities/order where the contract requires them.</p><p><strong>Your exercise:</strong> implement <code>listNotes</code> independently in the learner repository before inspecting the reference. Retain requirement-to-check mapping and one failed candidate, such as limiting before sorting. Explain its correction.</p><p><strong>Done:</strong> all declared criteria have observed evidence, callers receive the intended behavior and the actual diff remains scoped. <a href="./testing-debugging.html">Next: testing and debugging</a>.</p>',18)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
